styles.customCss:
/* The room around the text: a dark vignette that closes in on the edges. */
& {
  box-shadow: inset 0 0 140px rgba(0, 0, 0, 0.9);
}

/* Chapter titles glow like a candle behind a curtain, and the line under them is dried blood. */
& .chat-message-markdown h1 {
  text-shadow: 0 0 14px rgba(142, 27, 23, 0.55);
  border-bottom-color: #3a0c0b;
  padding-bottom: 0.4em;
}
& .chat-message-markdown h2,
& .chat-message-markdown h3 {
  letter-spacing: 0.12em;
}

/* Quotes: letters, diaries and whispers, set apart by a dark red bar and a stain. */
& .chat-message-markdown blockquote {
  background-color: rgba(92, 16, 16, 0.14);
  border-radius: 0;
}

/* Lists get a cross instead of a dot. */
& .chat-message-markdown ul {
  list-style: none;
  padding-left: 1.4em;
}
& .chat-message-markdown ul > li::before {
  content: "†";
  color: #8e1b17;
  display: inline-block;
  width: 1.4em;
  margin-left: -1.4em;
}

/* Links creep: pale green, and wavy when you reach for them. */
& .chat-message-markdown a {
  text-decoration: none;
}
& .chat-message-markdown a:hover {
  color: #b3261e;
  text-decoration: underline wavy;
}

/* Code and prompts: a terminal found in the cellar. */
& .chat-message-markdown pre {
  background-color: #120e0e;
  border-color: #2b1717;
}
& .chat-message-markdown code {
  background-color: #1a1313;
  color: #bfae9f;
}

/* Selecting text paints it red. */
& .chat-message-markdown ::selection {
  background: #5c1010;
  color: #fff;
}
